unsigned sw(const State&s){return (s.x87.fxsave.swd.flat&0xb880)|(s.sw.ie<<0)|(s.sw.de<<1)|(s.sw.ze<<2)|(s.sw.oe<<3)|(s.sw.ue<<4)|(s.sw.pe<<5)|(s.sw.sf<<6)|(s.sw.c0<<8)|(s.sw.c1<<9)|(s.sw.c2<<10)|(s.sw.c3<<14);}
std::array<std::byte,512> fx(const State&s){std::array<std::byte,512>b{};std::memcpy(b.data(),&s.x87,512);const auto status=static_cast<std::uint16_t>(sw(s));std::memcpy(b.data()+2,&status,2);std::memset(b.data()+6,0,18);for(unsigned i=0;i<8;++i){std::memcpy(b.data()+32+16*i,&s.st.elems[i].val,10);std::memcpy(b.data()+160+16*i,&s.vec[i],16);}return b;}
m4_runtime::Cpu32 cpu(const State&s){unsigned f=static_cast<unsigned>(s.rflag.flat)&~0xcd5U;f|=(s.aflag.cf<<0)|(s.aflag.pf<<2)|(s.aflag.af<<4)|(s.aflag.zf<<6)|(s.aflag.sf<<7)|(s.aflag.df<<10)|(s.aflag.of<<11);return {s.gpr.rax.dword,s.gpr.rcx.dword,s.gpr.rdx.dword,s.gpr.rbx.dword,s.gpr.rsp.dword,s.gpr.rbp.dword,s.gpr.rsi.dword,s.gpr.rdi.dword,f,s.gpr.rip.dword};}
