 s.sw.ie=s.sw.ze=s.sw.oe=s.sw.ue=s.sw.sf=s.sw.c0=s.sw.c1=s.sw.c2=s.sw.c3=0;s.sw.de=(sticky>>1)&1;s.sw.pe=(sticky>>5)&1;
